conditionals.code:
age = 20

if age < 13:
    print("Child")
elif age < 20:
    print("Teen")
else:
    print("Adult")

# Ternary equivalent
status = "Adult" if age >= 18 else "Minor"

for_loop.code:
# Iterate over range (0 to 4)
for i in range(5):
    print(i)

# Iterate over items
fruits = ["apple", "banana", "cherry"]
for fruit in fruits:
    print(fruit)

# Enumerate (index and value)
for idx, val in enumerate(fruits):
    print(f"{idx}: {val}")

while_loop.code:
count = 0
while count < 5:
    print(count)
    count += 1

    if count == 3:
        break # Exit loop early
else:
    # Executes if loop didn't 'break'
    print("Loop completed")

error_handling.code:
try:
    result = 10 / 0
except ZeroDivisionError as e:
    print(f"Math error: {e}")
except Exception as e:
    print(f"General error: {e}")
else:
    print("No errors occurred")
finally:
    print("Cleanup code runs always")

iterators.code:
def countdown(n):
    while n > 0:
        yield n
        n -= 1

for i in countdown(3):
    print(i)

